// AppMetadata captures an application's build-time metadata.
// This includes the application's unique identifier, human-friendly name,
// version information, and optional icon resource.
//
// Since: 2.2
type AppMetadata struct {
	// ID is the unique application identifier (e.g., "com.example.myapp")
	ID string
	// Name is the human-friendly application name (e.g., "My Application")
	Name string
	// Version is the application version string (e.g., "1.0.0")
	Version string
	// Build is the application build number
	Build int
	// Icon is the optional application icon resource
	Icon Resource
}

